def topo_sort(graph):
    in_degree = {}
    for node in graph:
        in_degree.setdefault(node, 0)
        for prereq in graph[node]:
            in_degree.setdefault(prereq, 0)
            in_degree[prereq] += 1

    # Use a sorted list to always pick lexicographically smallest ready node
    ready = sorted([n for n in in_degree if in_degree[n] == 0])

    result = []
    while ready:
        node = ready.pop(0)
        result.append(node)
        # For each node that depends on this node, decrement its in-degree
        for n in graph:
            if node in graph[n]:
                in_degree[n] -= 1
                if in_degree[n] == 0:
                    import bisect
                    bisect.insort(ready, n)

    if len(result) != len(in_degree):
        raise ValueError("Cycle detected")

    return result
