def is_private_ipv4(text):
    import re
    # Validate IPv4 format: 4 octets, each 0-255, separated by dots
    if not isinstance(text, str):
        return False
    parts = text.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part.isdigit():
            return False
        val = int(part)
        if val < 0 or val > 255:
            return False
    # Check if it falls within RFC1918 private ranges
    # 10.0.0.0/8 -> 10.x.x.x
    if parts[0] == '10':
        return True
    # 172.16.0.0/12 -> 172.16.x.x to 172.31.x.x
    if parts[0] == '172':
        if 16 <= int(parts[1]) <= 31:
            return True
    # 192.168.0.0/16 -> 192.168.x.x
    if parts[0] == '192' and parts[1] == '168':
        return True
    return False
